/* char-reki runtime: the Mirror (docs/characters/reki/KIT_MIRROR.md), appended to gameplay/buff/BuffFuncs by bbmod.

   Mirror Point (fenshen) adds rki_plant. rkiPlant, for Reki herself only, makes a copy of her on her spot with
   Taokaka's shadow piece (tk_create_shadow_player: a 201101 on her own moves; her boss's shadow function makes a boss
   actor); rkiTake (0.12 s, again at 0.24 s, both game-timed) takes it over: the copy's buffs cleared quietly (it would follow her and copy every action,
   and its end kills it), its AI stopped, rki_mirror on it (the stock shadow's flags and its end, 10.0 s), a
   dark tint. A second Mirror Point ends the first shadow.
   rkiEcho (rki_echo_<move>, half a second after the move starts): the planted shadow plays the same move from its
   spot, facing her. Only the moves that add the buff are repeated: never hurt, jump, dash or heal.
   rkiSwap (rki_swap, at a dash's start): with a shadow planted, she and the shadow trade places.
   Every step is guarded: a failure logs once (tag REKI) and the game goes on. */
(function () {
  var U = Util_1.U, CS = csharp_1;
  var S = globalThis.RKI || (globalThis.RKI = { m: new Map(), said: {} });
  S.pend = S.pend || {}; S.fcp = S.fcp || {}; S.U = U;  // for live checks from the room
  function log(k, m) {
    if (k && S.said[k]) return; if (k) S.said[k] = 1;
    try { if (globalThis.BBTR && BBTR.x && BBTR.x.log) { BBTR.x.log("REKI " + m); return } } catch (x) {}
    try { CS.System.IO.File.AppendAllText("@ROOT@/modlog.txt", (new Date()).toISOString() + " REKI " + m + "\n") } catch (x) {}
  }
  function actors() {
    var out = [];
    try { var L = CS.GamePlay.BattleBase.Cur.PlayerObjMgr.ActorList; for (var i = 0; i < L.Count; i++) out.push(L.get_Item(i)) }
    catch (x) { log("list", "actor list EXC " + x) }
    return out;
  }
  function alive(s) {
    try { return !!s && U.FpToFloat(s.Attr.HP) > 0 && s.BuffMgr.BuffExist("rki_mirror") } catch (x) { return false }
  }
  function fp2(x, y) { return U.Vector2ToFp2(new CS.UnityEngine.Vector2(x, y)) }
  function mine(e) { var r = S.m.get(e.UniqueId); return r && alive(r.s) ? r : null }

  /* ---- phase 2: the cards (docs/characters/reki/CARDS.md). Each card effect is a buff on one of her actions whose
     params name the cards it needs ("need") and the cards that switch it off ("skip"); a card is held when its
     trigger (Potential id * 10 + 1) is on her. */
  S.old = S.old || {}; S.xf = S.xf || new Map(); S.mark = S.mark || {}; S.own = S.own || {}; S.ownT = S.ownT || -9; S.trail = S.trail || {};
  var BULLET = 20110101;
  function now() { try { return U.FpToFloat(CS.GamePlay.BattleBase.Cur.BattleTimeFp) } catch (x) { return -1 } }
  function P(a, k) { var v = ""; try { v = a.GetS(k) } catch (x) { try { v = a.Get(k) } catch (y) {} } return v == null ? "" : String(v) }
  function own(e, pid) {
    var t = now(); if (t - S.ownT > 1 || t < S.ownT) { S.own = {}; S.ownT = t }
    var k = e.UniqueId + ":" + pid;
    if (!(k in S.own)) { var v = false; try { v = !!e.TriggerMgr.FindTriggerByIdxRange(pid * 10 + 1, pid * 10 + 5) } catch (x) {} S.own[k] = v }
    return S.own[k];
  }
  function cards(e, a) {
    var n = P(a, "need"), s = P(a, "skip");
    if (n && !n.split(",").every(function (p) { return own(e, +p) })) return false;
    if (s && s.split(",").some(function (p) { return own(e, +p) })) return false;
    // after / notafter: a marker set in the last 3 s (Final Chapter and Thunderhead share kuangbao_atk5)
    var af = P(a, "after"), na = P(a, "notafter"), t = now();
    if (af && !(t - (S.mark[e.UniqueId + af] || -9) < 3)) return false;
    if (na && t - (S.mark[e.UniqueId + na] || -9) < 3) return false;
    // in: only while she is in that action (a piece on a move that a variant copies: Thunder Drop on Plunge's landing)
    var ia = P(a, "in");
    if (ia) { var cur = ""; try { cur = String(e.ActionMgr.CurrentActionName) } catch (x) {} if (cur !== ia) return false }
    return true;
  }
  function mp(e, v, slot) {
    try { e.Attr.ChangeMPBy(U.FloatToFp(v), slot || 2); if (S.dbg) log(null, "mp" + (slot || 2) + " +" + v) } catch (x) { log("mp" + (slot || 2), "mp EXC " + x) }
  }
  function skill(e) {
    try { var k = e.SkillMgr.FindSkillByActionName(String(e.ActionMgr.CurrentActionName)); return k ? k.SkillActivate : null } catch (x) { return null }
  }
  // one projectile of her bullet actor (rkib1), playing action b at (x, y), flying along (dx, dy)
  function bullet(e, b, x, y, dx, dy) {
    try {
      var o = CS.GamePlay.BattleBase.Cur.BulletMgr.CreateBulletByParams(e, BULLET, fp2(x, y), fp2(dx, dy || 0), U.FloatToFp(1), b, skill(e), null);
      if (!o) log("nob" + b, "bullet " + b + " not created");
      else if (S.dbg) log(null, "fx " + b + " at " + x.toFixed(1) + "," + y.toFixed(1));
      return o;
    } catch (x) { log("bx" + b, "bullet " + b + " EXC " + x); return null }
  }
  function ab(e, b, card) { return own(e, card) ? b + "_ab" : b }
  // bursts or bolts along the line between two points (Swap Cut, Return Through)
  function path(e, x0, y0, x1, y1, b, n) {
    for (var i = 1; i <= n; i++) { var f = i / (n + 1); bullet(e, b, x0 + (x1 - x0) * f, y0 + (y1 - y0) * f, x1 > x0 ? 1 : -1, 0) }
  }
  function afterimage(e, x, y) {
    if (!own(e, 21112)) return;
    bullet(e, "atk_dashboom", x, y, e.Dir, 0);
    if (own(e, 21110)) bullet(e, "lei_warning", x, y, e.Dir, 0);           // hidden: Afterimage bursts twice
  }
  function enemies(e, cx, cy, r) {
    var out = [];
    actors().forEach(function (o) {
      try {
        if (!o || o.IsDead || o.Faction === e.Faction || U.FpToFloat(o.Attr.HP) <= 0) return;
        var d = Math.hypot(+o.Position.x - cx, +o.Position.y - cy); if (d <= r) out.push({ a: o, d: d });
      } catch (x) {}
    });
    out.sort(function (p, q) { return p.d - q.d });
    return out;
  }

  // which way the shadow swings or shoots: at the enemy Reki faces (the nearest one ahead of her), else her own facing.
  // It used to face Reki, so from the far side it struck away from the fight (the lead, 2026-10-22)
  function aim(e, sx, sy) {
    var ex = +e.Position.x, best = null;
    enemies(e, ex, +e.Position.y, 16).some(function (o) {
      var ox = +o.a.Position.x;
      if ((ox - ex) * e.Dir >= -0.5) { best = ox; return true }
      return false;
    });
    if (best === null) return e.Dir;
    return Math.abs(best - sx) < 0.3 ? e.Dir : (best > sx ? 1 : -1);
  }

  // the copy is drawn in full colour (Taokaka's are too). Her rig has the boss shadow's own page, the same layout
  // painted dark navy: the copy's renderer draws it as _MainTex through a property block (the glow mask stays hers,
  // so the orange rims come with it). The shared material is untouched; without the page, the old dark violet tint
  var PAGE = "actor/spine/leiji_caogao/leiji_caogao_shadow", TINT = [0.22, 0.16, 0.42, 0.9];
  function TYPEOF(t) { var f = (typeof puerts !== "undefined" && puerts.$typeof) || globalThis.$typeof; return f(t) }
  function page() {
    if (S.page === undefined) {
      try { S.page = U.GetSingleton(CS.NOAH.Asset.AssetManagerBase).LoadAssetByType(TYPEOF(CS.UnityEngine.Texture2D), PAGE) || null }
      catch (x) { S.page = null; log("tint", "shadow page EXC " + x) }
    }
    return S.page;
  }
  function tint(s) {
    try {
      var sa = s.Renderer.SkeletonAnim, sk = sa.skeleton, tx = page();
      if (tx) {
        var mr = sa.GetComponent(TYPEOF(CS.UnityEngine.MeshRenderer)), b = new CS.UnityEngine.MaterialPropertyBlock();
        mr.GetPropertyBlock(b); b.SetTexture("_MainTex", tx); mr.SetPropertyBlock(b);
        sk.R = 1; sk.G = 1; sk.B = 1; sk.A = 1;
      } else { sk.R = TINT[0]; sk.G = TINT[1]; sk.B = TINT[2]; sk.A = TINT[3] }
    } catch (x) { log("tint", "tint EXC " + x) }
  }

  // 0.5.7 (the lead's call on the testers' reports, 2026-11-13): the shadow's own hits deal 20% of hers, 40% with Heavy
  // Shadow (21134). The copy is a 201101 with her attack and none of her Potentials, so her +20% a card is not on it:
  // its share is set against her hit with the cards she holds now, through the stock final-damage buff 1302
  // (FinalDamAddRate, Strength = the share added; measured working on NaN, 2026-10). Heavy Shadow's old buff, 10741, is
  // FinalDamRate, the attribute 11111 uses, which was measured to add nothing (notes 2026-10).
  // Measured in game (window 2, 2026-11-14 04:11-04:13, cards.py v57_): the copy's own sword hits deal half of her hit
  // without cards before any buff (atk4_sh 37.9 against her 379.2 at strength -0.80; atk1_sh 160 against 320 at 0), and
  // its projectiles deal her hit without cards in full, untouched by a buff on the copy (Mirror Passes: 318.5 / 637.1
  // against her 573.4 / 1146.7 with 4 cards). So the copy's body gets 1302 at share / 0.5 - 1.
  // A 1302 on each projectile did nothing either (rerun, run_reki3.log: the shadow's wave 379.2, Mirror Passes 318.5 /
  // 637.1). Projectiles take the share from the spawn instead: every spawn of her bullet actors in her move tree scales
  // its damage by 1 - 0.02 x stacks of rki_shd + 0.05 x stacks of rki_shu on the actor that spawns it (steps
  // shadow_projectile_scale, the stock DamageScaleV expression with BuffStack, as Bullet's and Jin's). Reki carries
  // neither (x1); the shadow carries one, set here: 20% is 40 stacks of rki_shd, 328% (every card) 46 of rki_shu.
  var SHARE = 0.2, SHARE_HEAVY = 0.4, SHARE_PER_CARD = 0.2, BODY_NATIVE = 0.5, STACK_DN = 0.02, STACK_UP = 0.05, CARD_IDS = [];
  for (var ci = 21101; ci <= 21137; ci++) CARD_IDS.push(ci);
  S.share = S.share || {};
  function shadowShare(e, s, life) {
    try {
      var n = CARD_IDS.filter(function (p) { return own(e, p) }).length;
      var share = (own(e, 21134) ? SHARE_HEAVY : SHARE) * (1 + SHARE_PER_CARD * n);
      var st = share / BODY_NATIVE - 1;
      S.share[e.UniqueId] = { sid: s.UniqueId };
      if (Math.abs(st) > 0.001) s.BuffMgr.AddBuff("1302", U.FloatToFp(life + 1), U.FloatToFp(st), 1, e);
      // the projectiles' scale: their own damage is her hit without cards (x1), so the scale is the share itself
      var k = Math.round(Math.abs(share - 1) / (share < 1 ? STACK_DN : STACK_UP)), b = share < 1 ? "rki_shd" : "rki_shu", got = "";
      if (k > 0) {
        s.BuffMgr.AddBuff(b, U.FloatToFp(life + 1), U.FloatToFp(1), 1, e);
        s.BuffMgr.ChangeBuffStack(b, Math.min(k, 99));
        try { got = " (" + s.BuffMgr.GetBuffStack(b) + " read back)" } catch (x) {}
      }
      var rd = "?"; try { rd = U.FpToFloat(s.Attr.FinalAttr.get_Item(21)).toFixed(2) } catch (x) {}
      log(null, "shadow share " + share.toFixed(2) + " (cards " + n + ", body 1302 " + st.toFixed(2) + ", projectiles "
          + (k > 0 ? b + " x" + Math.min(k, 99) + got : "x1") + ", FinalDamAddRate " + rd + ")");
    } catch (x) { log("share", "shadow share EXC " + x) }
  }
  // the shadow's projectiles, every 0.02 s while it lives (rki_shadow_up on her): its Sword Waves become the _shw
  // copies, whose hit boxes have their own Id. A copy counts as its caster for a box Id's hold (0.4 s on the waves,
  // notes 2026-10), so with the shadow firing at once its wave never hit an enemy hers had just hit (v57_wave_*: no hit
  // from it in five cases; it hit after this, run_reki3.log)
  var SHW = { atk_jianqi_0: "atk_jianqi_0_shw", atk_jianqi_45: "atk_jianqi_45_shw", atk_jianqi_0_p: "atk_jianqi_0_p_shw", atk_jianqi_45_p: "atk_jianqi_45_p_shw" };
  function fromShadow(o, sid) {
    var c = o;
    for (var i = 0; i < 4; i++) {
      try { c = c.Caster } catch (x) { return false }
      if (!c) return false;
      if (c.UniqueId === sid) return true;
    }
    return false;
  }
  buffFuncs.rkiShBul = (e, t, a, r) => {
    try {
      if (e.Caster) return;
      var m = mine(e), sh = S.share[e.UniqueId]; if (!m || !sh || sh.sid !== m.s.UniqueId) return;
      var L = CS.GamePlay.BattleBase.Cur.BulletMgr.BulletList;
      for (var i = 0; i < L.Count; i++) {
        var o = L.get_Item(i);
        try {
          if (!fromShadow(o, m.s.UniqueId)) continue;
          var n = String(o.ActionMgr.CurrentActionName);
          if (SHW[n]) {
            o.ActionMgr.ChangeAction(SHW[n]);
            if (S.dbg) log(null, "shadow projectile " + n + " -> " + SHW[n]);
          }
        } catch (x) { log("shbul" + i, "shadow projectile EXC " + x) }
      }
    } catch (x) { log("shbul", "shadow projectiles EXC " + x) }
  };

  // one look, no timers: rki_plant calls it at 0.12 s and again at 0.24 s (S.pend: this plant still waits for its copy)
  function take(e, last) {
    // Taokaka's piece keeps one copy per caster and brings the same actor back on the next call (game, 2026-10-18),
    // so the last shadow's actor is a candidate again; one still carrying rki_mirror is a live shadow
    var best = null;
    actors().forEach(function (a) {
      try {
        if (a === e || a.UniqueId === e.UniqueId || a.BaseID !== e.BaseID) return;
        if (!a.Caster || a.Caster.UniqueId !== e.UniqueId) return;
        if (a.BuffMgr.BuffExist("rki_mirror")) return;
        if (!best || a.UniqueId > best.UniqueId) best = a;
      } catch (x) {}
    });
    if (!best) {
      if (!last) return;
      S.pend[e.UniqueId] = 0; S.fcp[e.UniqueId] = 0;
      var same = actors().filter(function (a) { try { return a.BaseID === e.BaseID && a !== e } catch (x) { return false } }).length;
      log(null, "plant: no shadow found (" + same + " other " + e.BaseID + " in the room)"); return;
    }
    var s = best, fc = !!S.fcp[e.UniqueId];
    S.fcp[e.UniqueId] = 0;
    // a shadow Final Chapter planted for itself lasts the move, not a Mirror Point's time
    var life = fc ? FC_SEC : (own(e, 21110) ? 20 : 10.0);
    // quietly: shadow_player_tk's end would run its KillSelf
    try { s.BuffMgr.RemoveAllQuiet() } catch (x) { log("rm", "copy buffs EXC " + x) }
    try { s.StopAI() } catch (x) {}
    try { s.BuffMgr.AddBuff("rki_mirror", U.FloatToFp(life), U.FloatToFp(1), 1, e) } catch (x) { log("add", "mirror buff EXC " + x) }
    shadowShare(e, s, life);
    try { s.Dir = e.Dir } catch (x) {}
    // Mirror Point Air: a shadow planted off the ground stays where it was planted (the game's own nogravity buff;
    // it takes hold at the next action change, so it goes on before the stand); ClearAll drops the fall speed the copy
    // was born with, which nogravity alone keeps (game, 2026-10-21)
    var air = false; try { air = e.ActorPosition.IsOffGround } catch (x) {}
    if (air) {
      try { s.BuffMgr.AddBuff("nogravity", U.FloatToFp(30), U.FloatToFp(1), 1, e); s.ActorPosition.ClearAll() } catch (x) { log("air", "air shadow EXC " + x) }
    }
    try { s.ActionMgr.ChangeAction("stand") } catch (x) {}
    tint(s);
    S.m.set(e.UniqueId, { s: s, x: +s.Position.x, y: +s.Position.y });
    S.pend[e.UniqueId] = 0;
    // her marker for as long as the shadow lives: the held Skill's switch into Mirror Recall needs it
    try { e.BuffMgr.AddBuff("rki_shadow_up", U.FloatToFp(life), U.FloatToFp(1), 1, e) } catch (x) { log("up", "shadow marker EXC " + x) }
    if (fc) { fcStrike(e, s); return }
    // a planted shadow stays where it was planted. It used to start following her at once with Long Mirror and Mirror
    // Strings, which took every Crossfire away (Boogy, 2026-11-10: "it just shouldn't do it as base"; "If it was just
    // something you could control, by recalling your shadow for example"): the follow now starts in rkiCall
    delete S.trail[e.UniqueId];
    try { e.BuffMgr.Remove("rki_trail") } catch (x) {}
    var hp = "?"; try { hp = U.FpToFloat(s.Attr.HP).toFixed(0) } catch (x) {}
    log(null, "plant: shadow #" + s.UniqueId + " at " + (+s.Position.x).toFixed(2) + " hp " + hp + " mirror " + s.BuffMgr.BuffExist("rki_mirror"));
  }

  // Final Chapter's own shadow (option A, card review 2026-10-23): set across from her, the far side of the enemy she
  // faces (else ahead of her), it plays the Ultra from there; it lasts the move
  var FC_SEC = 4;
  function fcStrike(e, s) {
    var ex = +e.Position.x, ey = +e.Position.y, nx = ex + e.Dir * 5;
    enemies(e, ex, ey, 12).some(function (o) {
      var ox = +o.a.Position.x;
      if ((ox - ex) * e.Dir >= -0.5) { nx = ox + e.Dir * 2.5; return true }
      return false;
    });
    try { s.ActorPosition.TeleportForce(fp2(nx, ey)) } catch (x) { log("fctp", "final chapter shadow move EXC " + x) }
    var m = S.m.get(e.UniqueId); if (m) { m.x = nx; m.y = ey }
    s.Dir = aim(e, nx, ey);
    s.ActionMgr.ChangeAction("kuangbao_atk3_sh");
    if (String(s.ActionMgr.CurrentActionName) !== "kuangbao_atk3_sh") s.ActionMgr.ChangeAction("kuangbao_atk3");
    log(null, "final chapter: own shadow at " + nx.toFixed(2) + " -> " + s.ActionMgr.CurrentActionName);
  }

  // Taokaka's piece makes the copy; rkiTake (0.12 / 0.24 s) takes it over
  function plant(e, fc) {
    S.pend[e.UniqueId] = 1;
    S.fcp[e.UniqueId] = fc ? 1 : 0;
    e.BuffMgr.AddBuff("tk_create_shadow_player", U.FloatToFp(0.3), U.FloatToFp(1), 1, e);
  }
  // a copy is born inside Mirror Point too: only Reki herself (no Caster) makes one
  buffFuncs.rkiPlant = (e, t, a, r) => {
    try {
      if (e.Caster) return;
      // again moves it: the old shadow ends first (Taokaka's piece makes no second copy while one lives)
      var old = mine(e);
      if (old) {
        S.old[e.UniqueId] = { x: +old.s.Position.x, y: +old.s.Position.y };
        afterimage(e, +old.s.Position.x, +old.s.Position.y);
        try { old.s.BuffMgr.Remove("rki_mirror") } catch (x) {} S.m.delete(e.UniqueId);
      }
      delete S.trail[e.UniqueId];   // planting again ends the follow
      try { e.BuffMgr.Remove("rki_trail") } catch (x) {}
      plant(e, false);
    } catch (x) { log("plant", "plant EXC " + x) }
  };
  // Final Chapter with no shadow planted: one of its own for the move (a planted one echoes as before, rki_c_echo_fc)
  buffFuncs.rkiFcPlant = (e, t, a, r) => {
    try {
      if (e.Caster || mine(e) || S.pend[e.UniqueId] || !cards(e, a)) return;
      plant(e, true);
    } catch (x) { log("fcplant", "final chapter plant EXC " + x) }
  };
  buffFuncs.rkiTake = (e, t, a, r) => {
    try {
      if (e.Caster || !S.pend[e.UniqueId]) return;
      take(e, S.pend[e.UniqueId]++ >= 2);
    } catch (x) { log("take", "take EXC " + x) }
  };

  // 0.5.10: empty. The shadow's Rage Step form makes its own effect projectile now (steps shadow_fx), as every form does
  var ECHO_FX = {};
  buffFuncs.rkiEcho = (e, t, a, r) => {
    try {
      var m = mine(e); if (!m) return;
      if (e.Caster || !cards(e, a)) return;
      // 0.5.7 (the testers, 2026-11-12; card 21137): the shadow's Raimei restores MP to her, once per echo. Given
      // before the trail's return, so a trailing shadow's Raimei pays too
      var g = +P(a, "mp"), gc = +P(a, "mpcard");
      if (g && (!gc || own(e, gc))) mp(e, g);
      // a trailing shadow replays the move itself, half a second behind, from where she made it (rkiTrail)
      if (S.trail[e.UniqueId] && e.BuffMgr.BuffExist("rki_trail")) return;
      var act = P(a, "act");
      if (!act) { log("noact", "echo: no move name"); return }
      var s = m.s;
      // an air move echoed by a shadow on the ground: its ground form ("ground"), so the shot is not fired into the floor
      if (P(a, "ground")) { var off = false; try { off = s.ActorPosition.IsOffGround } catch (x) {} if (!off) act = P(a, "ground") }
      try { s.ActorPosition.TeleportForce(fp2(m.x, m.y)) } catch (x) { log("tp", "echo return EXC " + x) }
      s.Dir = aim(e, m.x, m.y);
      s.ActionMgr.ChangeAction(act + "_sh");
      if (String(s.ActionMgr.CurrentActionName) !== act + "_sh") s.ActionMgr.ChangeAction(act);
      // the copy draws no effect of its own for these moves: she plays it at its spot (an effect-only projectile)
      if (ECHO_FX[act]) bullet(e, ECHO_FX[act], m.x, m.y, s.Dir, 0);
      log(null, "echo " + act + " -> " + s.ActionMgr.CurrentActionName);
    } catch (x) { log("echo", "echo EXC " + x) }
  };

  // the trailing shadow (hidden 211037), every 0.02 s while rki_trail lasts: it stands where she stood half a second
  // ago, faces as she faced and replays every move she started then, from its first frame (ActionChangeAutoId tells a
  // move started again from one still playing). An attack it replays as the shadow form (_sh, effects unbound) where
  // her tree has one. It used to take up only her steps and stand still through everything else (the lead,
  // 2026-10-23: "its just static it needs to copy rekis move animations"). Taokaka's astral copy follows her the same way
  var NOCOPY = /^(behit|push_|knockdown|dead|reborn|born|pvp_born|winpose|StagePass|paid_show|bornshow|standUp|quickStand|reactive|addHP|fenshen|summon)|_show$/;
  // 0.5.10: the follow also takes the shadow's forms of her run (the copy has no stick to hold a run: Boogy, "the shadow
